"""Build self-contained project demos from reproducible Python result JSON."""
from pathlib import Path
import json
import html

ROOT = Path(__file__).resolve().parents[1]
REPOS = ROOT.parent
PROJECTS = [
 ('charge-insight','充电需求洞察','应用与优化','CI'),
 ('smartcharge-lab','充电调度实验台','应用与优化','SC'),
 ('openvitac-data-audit','多模态轨迹质检','机器人与数据','VT'),
 ('vla-data-preflight','VLA 训练前预检','机器人与数据','VP'),
 ('embodied-eval-lab','具身评估分析','实验与研究','EE'),
 ('data-efficient-learning-lab','数据预算实验','实验与研究','DB'),
]
OWNER = 'qianchen223307-lang'

CSS = r'''
:root{--ink:#172723;--muted:#667872;--paper:#f6f8f5;--line:#dfe7df;--green:#176c54;--mint:#dff3e9;--blue:#3659b8;--shadow:0 12px 34px #1f49350a}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.65 'Segoe UI','Microsoft YaHei',system-ui,sans-serif}a{color:inherit;text-decoration:none}button,input{font:inherit}button,a,input{outline-offset:4px}button{cursor:pointer}.sidebar{position:fixed;inset:0 auto 0 0;width:244px;padding:34px 24px;background:#152d27;color:#c4d9cf;display:flex;flex-direction:column;z-index:10}.brand{color:#fff;font-size:23px;font-weight:750;letter-spacing:-1px}.brand span{color:#9ce0b8}.subbrand{font:10px/1.8 monospace;letter-spacing:2.6px;margin:8px 0 38px;color:#92b6a4}.nav-label{color:#80a28f;font:10px monospace;letter-spacing:2px;margin:22px 12px 10px}.project-link{display:flex;align-items:center;gap:12px;padding:12px 10px;border-radius:9px;font-size:13px;transition:.2s}.project-link b{font:10px monospace;color:#7d9e8d}.project-link:hover,.project-link.active{background:#2c493e;color:#fff}.project-link.active b{color:#9ce0b8}.side-footer{margin-top:auto;border-top:1px solid #365146;padding-top:22px;font-size:11px;color:#8fb19f}.side-footer a{display:block;color:#d4e8dc;margin-top:8px;word-break:break-all}main{margin-left:244px;padding:28px 52px 54px;max-width:1680px}.topbar{display:flex;justify-content:space-between;gap:16px;align-items:center;padding-bottom:20px;border-bottom:1px solid var(--line);font-size:12px;color:var(--muted)}.topbar .links{display:flex;gap:22px}.topbar a:hover{color:var(--green)}.eyebrow{font:11px monospace;letter-spacing:2px;color:var(--green);font-weight:700;margin:44px 0 14px}.hero{position:relative;padding-bottom:30px}.hero:after{content:'+';position:absolute;right:24px;top:0;font:150px/1 monospace;color:#e7eee5;z-index:-1}h1{font-size:clamp(32px,3.9vw,58px);line-height:1.2;letter-spacing:-2px;max-width:950px;margin:0 0 20px;font-weight:760}.tagline{font-size:17px;max-width:820px;color:var(--muted);line-height:1.85}.badge{display:inline-flex;align-items:center;gap:7px;background:var(--mint);color:var(--green);font-size:11px;border-radius:24px;padding:5px 12px;margin-top:14px}.badge:before{content:'';width:6px;height:6px;background:#3f9971;border-radius:50%}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;margin:34px 0 14px}h2{font-size:18px;margin:0;letter-spacing:-.4px}.section-no{font:11px monospace;color:#8ca197;margin-right:12px}.section-caption{color:var(--muted);font-size:12px}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:13px;margin:6px 0 24px}.metric{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px 20px 17px;box-shadow:var(--shadow)}.metric-label{font-size:11px;color:var(--muted);min-height:20px}.metric-value{font-size:30px;font-weight:700;letter-spacing:-1px;margin-top:6px;word-break:break-word}.metric-value small{font-size:12px;font-weight:500;letter-spacing:0;color:var(--muted);margin-left:4px}.metric-detail{color:var(--muted);font-size:11px;margin-top:5px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.tab{border:1px solid var(--line);background:#fff;border-radius:8px;padding:8px 14px;color:var(--muted);font-size:12px}.tab.selected{background:var(--ink);border-color:var(--ink);color:#fff}.summary{font-size:14px;color:#52695d;max-width:1100px;margin:14px 0 22px}.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.panel{background:#fff;border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);padding:23px;min-width:0}.chart-top{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:14px}.panel h3{font-size:14px;margin:0;font-weight:650}.tiny-button{background:none;border:1px solid var(--line);border-radius:5px;color:var(--muted);font:10px monospace;padding:3px 7px;white-space:nowrap}.chart{display:block;width:100%;height:auto;overflow:visible}.legend{display:flex;gap:13px;flex-wrap:wrap;font-size:11px;margin:12px 0 2px}.legend span{display:inline-flex;align-items:center;gap:6px}.legend i{display:inline-block;width:8px;height:8px;border-radius:50%}.table-panel{margin-top:20px}.table-head{display:flex;justify-content:space-between;gap:15px;align-items:center;margin-bottom:16px}.search{border:1px solid var(--line);border-radius:6px;padding:5px 9px;width:180px;font-size:11px;background:#fbfdfa}.table-scroll{overflow:auto;max-height:440px}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:12px}th,td{text-align:left;border-bottom:1px solid #edf1ec;padding:10px 13px}th{background:#f1f6ef;color:#607766;font-size:10px;font-weight:600;position:sticky;top:0}tbody tr:hover{background:#f6faf4}td{font-variant-numeric:tabular-nums}.table-note{font-size:11px;color:var(--muted);margin:12px 0 0}.empty{text-align:center;color:var(--muted);padding:24px}.lower{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.lower ol,.lower ul{padding-left:20px;margin:14px 0 0;color:#5c7065;font-size:12px}.lower li{margin:9px 0;padding-left:3px}.run{background:#17382b;color:#e0eee4;padding:22px;border-radius:12px;margin-top:20px;display:flex;justify-content:space-between;align-items:center;gap:15px}.run .label{color:#99bfa6;font-size:11px;margin-bottom:5px}.run code{font-size:12px;word-break:break-all}.copy{background:#315641;color:#d9eddf;border:1px solid #4c7058;padding:7px 12px;border-radius:6px;font-size:11px}footer{display:flex;justify-content:space-between;gap:20px;margin-top:35px;padding-top:20px;border-top:1px solid var(--line);font-size:11px;color:var(--muted)}footer a{text-decoration:underline}.mobile-brand{display:none}.status{font:10px monospace;color:var(--muted)}.gallery{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}.gallery figure{margin:0;flex:1;min-width:200px}.gallery img{width:100%;border-radius:8px;border:1px solid var(--line);image-rendering:auto}.gallery figcaption{font-size:11px;color:var(--muted)}@media(min-width:1600px){main{padding-left:64px;padding-right:64px}}@media(max-width:1100px){.sidebar{width:210px;padding:28px 16px}main{margin-left:210px;padding:25px}.charts{grid-template-columns:1fr}.hero:after{display:none}}@media(max-width:760px){.sidebar{display:none}main{margin:0;padding:18px}.topbar{flex-wrap:wrap}.mobile-brand{display:inline;font-weight:700;color:var(--green)}.eyebrow{margin-top:28px}h1{letter-spacing:-1px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.metric{padding:15px}.metric-value{font-size:25px}.lower{grid-template-columns:1fr}.panel{padding:17px}.run{align-items:start}.section-caption{display:none}footer{flex-direction:column;gap:6px}.table-head{align-items:start;flex-direction:column}.search{width:100%}}
'''

JS = r'''
const D=JSON.parse(document.getElementById('project-data').textContent);
const palette=['#277c59','#3b61b8','#d59442','#a363a9','#62aeb0','#7e8e56'];
const $=s=>document.querySelector(s);
function text(tag,value,cls){let e=document.createElement(tag);e.textContent=value??'';if(cls)e.className=cls;return e}
function number(v){if(typeof v!=='number')return v??'—';if(!Number.isFinite(v))return '—';return Math.abs(v)>=1000? v.toLocaleString('en-US',{maximumFractionDigits:2}):v.toLocaleString('en-US',{maximumFractionDigits:4})}
function download(filename,content,type='text/csv'){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function metricCards(metrics){$('#metrics').replaceChildren();(metrics||[]).forEach(m=>{let c=text('div','', 'metric');c.append(text('div',m.label,'metric-label'));let n=text('div',number(m.value),'metric-value');if(m.unit)n.append(text('small',m.unit));c.append(n);if(m.detail)c.append(text('div',m.detail,'metric-detail'));$('#metrics').append(c)})}
function drawChart(chart,index){let panel=text('article','','panel');let top=text('div','','chart-top');top.append(text('h3',chart.title));let btn=text('button','CSV ↓','tiny-button');btn.onclick=()=>{let esc=x=>'"'+String(x??'').replaceAll('"','""')+'"';let rows=[['label',...chart.series.map(s=>s.name)],...chart.labels.map((l,i)=>[l,...chart.series.map(s=>s.values[i])])];download(D.slug+'-chart-'+index+'.csv',rows.map(r=>r.map(esc).join(',')).join('\n'))};top.append(btn);panel.append(top);
 let ns='http://www.w3.org/2000/svg', svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 600 294');svg.setAttribute('role','img');svg.setAttribute('aria-label',chart.title);svg.classList.add('chart');let title=document.createElementNS(ns,'title');title.textContent=chart.title;svg.append(title);
 const L=54,R=584,T=27,B=246;const vals=chart.series.flatMap(s=>s.values).filter(v=>typeof v==='number'&&Number.isFinite(v));let lo=Math.min(0,...vals),hi=Math.max(...vals,1);if(hi===lo)hi=lo+1;const x=i=>L+i*(R-L)/Math.max(1,chart.labels.length-1),y=v=>B-(v-lo)/(hi-lo)*(B-T);
 const el=(name,attrs,content)=>{let e=document.createElementNS(ns,name);for(let [k,v]of Object.entries(attrs))e.setAttribute(k,String(v));if(content!==undefined)e.textContent=content;svg.append(e);return e};
 for(let i=0;i<5;i++){let v=lo+(hi-lo)*i/4, yy=y(v);el('line',{x1:L,y1:yy,x2:R,y2:yy,stroke:'#e8eee7','stroke-dasharray':'3 4'});el('text',{x:L-9,y:yy+4,'text-anchor':'end',fill:'#829489','font-size':10},Math.abs(v)>=1000?(v/1000).toFixed(1)+'k':Number(v.toPrecision(3)).toString())}
 el('text',{x:L,y:13,fill:'#829489','font-size':10},chart.y_label||'');let step=Math.max(1,Math.ceil(chart.labels.length/6));chart.labels.forEach((label,i)=>{if(i%step===0||i===chart.labels.length-1)el('text',{x:chart.kind==='bar'?L+(i+.5)*(R-L)/Math.max(1,chart.labels.length):x(i),y:B+22,'text-anchor':'middle',fill:'#829489','font-size':9},String(label).slice(0,18))});
 chart.series.forEach((s,k)=>{let color=palette[k%palette.length];if(chart.kind==='bar'){let gw=(R-L)/Math.max(1,chart.labels.length),bw=gw*.72/chart.series.length;s.values.forEach((v,i)=>{if(typeof v!=='number'||!Number.isFinite(v))return;let xx=L+gw*i+gw*.14+k*bw;let rect=el('rect',{x:xx,y:Math.min(y(v),y(0)),width:Math.max(1,bw-2),height:Math.max(1,Math.abs(y(0)-y(v))),rx:2,fill:color});let tip=document.createElementNS(ns,'title');tip.textContent=s.name+' · '+chart.labels[i]+': '+number(v);rect.append(tip)})}else{let path='',active=false;s.values.forEach((v,i)=>{if(typeof v!=='number'||!Number.isFinite(v)){active=false;return}path+=(active?'L':'M')+x(i).toFixed(2)+' '+y(v).toFixed(2)+' ';active=true});el('path',{d:path,fill:'none',stroke:color,'stroke-width':2.2,'stroke-linecap':'round','stroke-linejoin':'round'});if(s.values.length<40)s.values.forEach((v,i)=>{if(typeof v!=='number'||!Number.isFinite(v))return;let c=el('circle',{cx:x(i),cy:y(v),r:3,fill:color});let tip=document.createElementNS(ns,'title');tip.textContent=s.name+' · '+chart.labels[i]+': '+number(v);c.append(tip)})}});
 if(chart.kind!=='bar'&&chart.labels.length){let hit=el('rect',{x:L,y:T,width:R-L,height:B-T,fill:'transparent'}),cross=el('line',{x1:L,x2:L,y1:T,y2:B,stroke:'#81998a','stroke-dasharray':'4 4',visibility:'hidden'}),tip=el('text',{x:R,y:T-8,'text-anchor':'end',fill:'#52695d','font-size':10});hit.addEventListener('mousemove',event=>{let pt=svg.createSVGPoint();pt.x=event.clientX;pt.y=event.clientY;let loc=pt.matrixTransform(svg.getScreenCTM().inverse()),i=Math.max(0,Math.min(chart.labels.length-1,Math.round((loc.x-L)/(R-L)*(chart.labels.length-1))));cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('visibility','visible');tip.textContent=chart.labels[i]+' · '+chart.series.map(s=>s.name+': '+number(s.values[i])).join(' / ')});hit.addEventListener('mouseleave',()=>{cross.setAttribute('visibility','hidden');tip.textContent=''})}
 panel.append(svg);let legend=text('div','','legend');chart.series.forEach((s,i)=>{let item=text('span',s.name);let dot=document.createElement('i');dot.style.background=palette[i%palette.length];item.prepend(dot);legend.append(item)});panel.append(legend);$('#charts').append(panel)
}
function drawTable(t){let panel=text('article','','panel table-panel'),head=text('div','','table-head');head.append(text('h3',t.title));let search=document.createElement('input');search.type='search';search.placeholder='搜索表格 / Search';search.className='search';search.setAttribute('aria-label','搜索 '+t.title);head.append(search);panel.append(head);let wrap=text('div','','table-scroll'),table=document.createElement('table'),thead=document.createElement('thead'),hr=document.createElement('tr');t.columns.forEach(c=>hr.append(text('th',c)));thead.append(hr);table.append(thead);let body=document.createElement('tbody');let render=q=>{body.replaceChildren();(t.rows||[]).filter(row=>row.map(number).join(' ').toLowerCase().includes(q)).forEach(row=>{let tr=document.createElement('tr');row.forEach(v=>tr.append(text('td',number(v))));body.append(tr)})};render('');search.oninput=()=>render(search.value.toLowerCase());table.append(body);wrap.append(table);panel.append(wrap);if(t.note)panel.append(text('p',t.note,'table-note'));$('#tables').append(panel)}
function show(s){const charts=s.charts?.length?s.charts:(D.charts||[]).map(c=>s===D?c:{...c,title:c.title+' · 正常样例参考'});$('#summary').textContent=s.summary||D.summary||'';metricCards(s.metrics||D.metrics);$('#charts').replaceChildren();charts.forEach(drawChart);$('#tables').replaceChildren();(s.tables||D.tables||[]).forEach(drawTable);$('#chart-block').hidden=!charts.length;$('#table-block').hidden=!(s.tables||D.tables||[]).length}
$('#title').textContent=D.title;$('#tagline').textContent=D.tagline;$('#category').textContent=D.category;$('#data-kind').textContent=D.data_kind||'结果来自仓库中的可复现实验';document.title=D.title+' · QC Lab';
(D.method||[]).forEach(s=>$('#method').append(text('li',s)));(D.limitations||[]).forEach(s=>$('#limitations').append(text('li',s)));
if(D.scenarios?.length){D.scenarios.forEach((s,i)=>{let b=text('button',s.label,'tab'+(i===0?' selected':''));b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');show(s)};$('#tabs').append(b)});show(D.scenarios[0])}else show(D);
if(D.images?.length){D.images.forEach(im=>{let fig=document.createElement('figure'),img=document.createElement('img');img.src=im.src;img.alt=im.caption||D.title;fig.append(img,text('figcaption',im.caption||''));$('#gallery').append(fig)})}
$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#command').textContent);$('#copy').textContent='已复制 ✓'}catch{$('#copy').textContent='请选中命令复制'}};
'''

def build(slug):
    repo=REPOS/slug
    src=repo/'docs'/'data.json'
    if not src.exists():
        return False
    data=json.loads(src.read_text(encoding='utf-8-sig'))
    data['slug']=slug
    data['data_kind']={
      'real_observations_preprocessed':'公开真实观测 · 作者已预处理 · 本地实测',
      'real-public-data':'公开真实数据 · CPU 实测',
      'synthetic':'合成场景 · 可复现演示',
      'synthetic_demo':'自建样例 · 工具真实运行',
    }.get(data.get('data_kind'), data.get('data_kind','可复现实验'))
    nav=[]
    last=None
    for s,t,c,code in PROJECTS:
        if c!=last:nav.append(f'<div class="nav-label">{c}</div>');last=c
        nav.append(f'<a class="project-link {"active" if s==slug else ""}" href="https://{OWNER}.github.io/{s}/"><b>{code}</b>{t}</a>')
    payload=json.dumps(data,ensure_ascii=False,allow_nan=False).replace('</',r'<\/')
    page=f'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(data.get('tagline',''),quote=True)}"><meta name="theme-color" content="#152d27"><title>{html.escape(data['title'])} · QC Lab</title><style>{CSS}</style></head>
<body><aside class="sidebar"><a class="brand" href="https://github.com/{OWNER}">QC<span> / </span>LAB</a><div class="subbrand">BUILD · MEASURE · EXPLAIN</div>{''.join(nav)}<div class="side-footer">Independent projects / AI-assisted<br>独立实现 · 可复现实验<a href="https://github.com/{OWNER}">@{OWNER} ↗</a></div></aside>
<main><header class="topbar"><span><b class="mobile-brand">QC / LAB · </b>PROJECT NOTEBOOK <span aria-hidden="true"> / </span> <span id="category"></span></span><div class="links"><a href="https://github.com/{OWNER}/{slug}">源码 ↗</a><a href="https://github.com/{OWNER}/{slug}/actions">验证记录 ↗</a><a href="data.json" download>结果 JSON ↓</a></div></header>
<section class="hero"><div class="eyebrow">APPLIED INTELLIGENCE / REPRODUCIBLE WORK</div><h1 id="title"></h1><p id="tagline" class="tagline"></p><div class="badge" id="data-kind"></div></section>
<section aria-label="交互结果"><div class="section-heading"><h2><span class="section-no">01</span>结果与探索</h2><span class="section-caption">从 Python 运行结果生成 · 可切换样例</span></div><div id="tabs" class="tabs"></div><p class="summary" id="summary"></p><div class="metrics" id="metrics"></div><div class="gallery" id="gallery"></div><div id="chart-block"><div class="charts" id="charts"></div></div><div id="table-block"><div id="tables"></div></div></section>
<section><div class="section-heading"><h2><span class="section-no">02</span>方法与边界</h2><span class="section-caption">理解结果的依据</span></div><div class="lower"><article class="panel"><h3>实现了什么</h3><ol id="method"></ol></article><article class="panel"><h3>结果如何解读</h3><ul id="limitations"></ul></article></div><div class="run"><div><div class="label">本地重建结果 · 安装方法见仓库 README</div><code id="command">python -m {slug.replace('-','_')} demo</code></div><button class="copy" id="copy">复制命令</button></div></section>
<footer><span>© 2026 {OWNER} · 使用 AI 辅助开发，结果由代码实跑生成。</span><a href="https://github.com/{OWNER}/{slug}#readme">来源、运行方法与能力边界 ↗</a></footer></main>
<script id="project-data" type="application/json">{payload}</script><script>{JS}</script></body></html>'''
    (repo/'docs'/'index.html').write_text(page,encoding='utf-8')
    (repo/'docs'/'.nojekyll').write_text('',encoding='utf-8')
    return True

if __name__=='__main__':
    print(ROOT.name, 'built' if build(ROOT.name) else 'waiting for results')
